import React from 'react';
import InputField from '../components/InputField';

const BuyerForm = ({ user, onNavigate }) => {
    return (
        <form className="space-y-4 max-w-2xl mx-auto">
            <InputField label="Company Name" type="text" placeholder="e.g. Green Fresh Ltd" required />
            <InputField label="Contact Person" type="text" placeholder="e.g. John Doe" required />
            <InputField label="Phone Number" type="tel" placeholder="e.g. +254700123456" required />
            <InputField label="Email" type="email" placeholder="e.g. buyer@company.com" required />
            <InputField label="Crop Interested In" type="text" placeholder="e.g. Avocado" required />
            <InputField label="Expected Quantity" type="text" placeholder="e.g. 5 tonnes" required />
            <button type="submit" className="bg-teal-700 text-white px-6 py-2 rounded hover:bg-teal-800">
                Submit Offer
            </button>
        </form>
    );
};

export default BuyerForm;
